"""Reviewed logic tables for the Linux STIGs generated by gen_rhel9.py from another platform's reviewed rules.

Oracle Linux 8/9 and RHEL 10 were derived from the RHEL 9 modules by DISA rule TITLE (gen_oracle_linux.py,
retired 2026-11-18): a title match is not a check match, and it put ids on the wrong settings. A platform table
is now built rule by rule against the platform's OWN check text:

  T.reuse(<platform id>, <RHEL 9 id>, **patch)
        the platform's check is the same check as the reviewed RHEL 9 rule (same setting, same file or command,
        same expected value and comparison). The RHEL 9 spec is copied with the RHEL 9 id and its rule ident
        (attestation keys, comments, expect text) rewritten to the platform id; `patch` replaces whole fields
        where only a detail differs (an expected value, a dropped Not Applicable clause), and the difference is
        recorded in the table next to the call.
  T.R(...)
        the platform's own logic, written from its check text (same spec format as rhel9_rules.R).

Section helpers: every helper definition of the source tables is in a pool; a section carries only the helper
definitions its rules reference (transitively), so a module never ships an unused helper from another
platform. T.finish() returns RULES and SECTION_HELPERS for the generator.
"""
import copy, re

import rhel9_rules


def _chunks(text):
    out = []
    for para in re.split(r"\n\s*\n", text.strip()):
        code = "\n".join(l for l in para.strip().splitlines() if not l.lstrip().startswith("#"))
        m = re.match(r"(?:default )?([a-z_][a-zA-Z0-9_]*)", code.strip())
        if m:
            out.append((m.group(1), para.strip()))
    return out


def _idents(text):
    return set(re.findall(r"\b([a-z_][a-zA-Z0-9_]*)\b", re.sub(r'"(?:[^"\\\n]|\\.)*"|`[^`]*`', '""', text)))


def ident(sid):
    return sid.lower().replace("-", "_")


class Table:
    def __init__(self, sources=(rhel9_rules,)):
        """sources: modules with RULES / SECTION_HELPERS whose specs may be reused (RHEL 9, or another platform's
        reviewed table); a reused spec keeps the sections' helper names, so those modules' helpers are pooled."""
        self.RULES = {}
        self.src = {}
        self.extra = {}       # section -> helper text written for this platform
        self.pool = {}        # section -> [(name, paragraph)] in source order
        for mod in sources:
            self.src.update(mod.RULES)
            # a platform table exports only the helpers it wrote (OWN_HELPERS); the RHEL 9 ones come from rhel9_rules
            for sec, text in getattr(mod, "OWN_HELPERS", mod.SECTION_HELPERS).items():
                seen = {p for _, p in self.pool.get(sec, [])}
                # a platform table's helpers repeat the RHEL 9 helpers it pulled: pool each paragraph once
                self.pool.setdefault(sec, []).extend(c for c in _chunks(text) if c[1] not in seen)

    def helpers(self, sec, text, replace=False):
        """Platform helpers for a section. replace=True drops the source helpers of the same names first (the
        platform reads another fact under the same helper, e.g. OL 8 audit rules from /etc/audit/audit.rules)."""
        if replace:
            names = {n for n, _ in _chunks(text)}
            self.pool[sec] = [(n, p) for n, p in self.pool.get(sec, []) if n not in names]
        self.extra[sec] = (self.extra.get(sec, "").strip() + "\n\n" + text.strip()).strip()

    def R(self, sec, sid, name, ev, alts, green, bad, expect, fix, comment="", kind="machine", attest_alts=(), na=(),
          na_expect="", na_cases=(), pass_cases=(), green_na=None):
        assert sid not in self.RULES, f"{sid} defined twice"
        if attest_alts and kind == "machine":
            kind = "machine+attestation"
        self.RULES[sid] = dict(sec=sec, name=name, ev=[tuple(e) for e in ev], alts=alts, green=green, bad=list(bad),
                               expect=expect, fix=fix, comment=comment, kind=kind,
                               attest_alts=list(attest_alts), na=list(na), na_expect=na_expect,
                               na_cases=list(na_cases), pass_cases=list(pass_cases))
        if green_na:
            self.RULES[sid]["green_na"] = green_na

    def reuse(self, sid, src_sid, **patch):
        assert sid not in self.RULES, f"{sid} defined twice"
        spec = copy.deepcopy(self.src[src_sid])
        a, b, ia, ib = src_sid, sid, ident(src_sid), ident(sid)

        def sub(o):
            if isinstance(o, str):
                return o.replace(a, b).replace(ia, ib)
            if isinstance(o, list):
                return [sub(x) for x in o]
            if isinstance(o, tuple):
                return tuple(sub(x) for x in o)
            if isinstance(o, dict):
                return {sub(k): sub(v) for k, v in o.items()}
            return o

        spec = sub(spec)
        for k, v in patch.items():
            assert k in spec or k == "green_na", f"{sid}: unknown spec field {k}"
            spec[k] = v
        if spec["attest_alts"] and spec["kind"] == "machine":
            spec["kind"] = "machine+attestation"
        if not spec["attest_alts"] and spec["kind"] == "machine+attestation":
            spec["kind"] = "machine"
        spec["reused_from"], spec["reused_to"] = src_sid, sid
        self.RULES[sid] = spec

    def finish(self):
        helpers = {}
        for sec in sorted({s["sec"] for s in self.RULES.values()}):
            own = _chunks(self.extra.get(sec, ""))
            clash = {n for n, _ in own} & {n for n, _ in self.pool.get(sec, [])}
            if clash:
                raise SystemExit(f"{sec}: platform helpers redefine source helpers {sorted(clash)}")
            pool = list(self.pool.get(sec, [])) + own
            refs = set()
            for s in self.RULES.values():
                if s["sec"] == sec:
                    for alt in s["alts"] + s["attest_alts"] + s["na"]:
                        refs |= _idents("\n".join(alt))
            keep, changed = set(), True   # indexes into pool: every clause of a referenced definition
            while changed:
                changed = False
                for i, (n, para) in enumerate(pool):
                    if n in refs and i not in keep:
                        keep.add(i)
                        refs |= _idents(para)
                        changed = True
            text = "\n\n".join(p for i, (n, p) in enumerate(pool) if i in keep)
            # a helper that names a reused rule's own attestation key (e.g. _aide_notifies) carries the platform id
            for spec in self.RULES.values():
                if spec["sec"] == sec and spec.get("reused_from"):
                    text = text.replace(ident(spec["reused_from"]), ident(spec["reused_to"]))
                    text = text.replace(spec["reused_from"], spec["reused_to"])
            if text:
                helpers[sec] = text
        return self.RULES, helpers
